// neote-hello — the smallest useful Neote package.
// The `neote` object is injected into your package scope.
// Register lifecycle hooks so the IDE can start/stop you cleanly.

neote.onEnable(function () {
  neote.log("neote-hello enabled!", "success");
  neote.toast("Hello from " + neote.pkg.name + " v" + neote.pkg.version, "success");

  // Add a clickable widget to the left side of the status bar.
  neote.statusBar.add({
    id: "neote-hello",
    position: "left",
    html: '<i class="fa-solid fa-hand-sparkles text-neote-violet"></i>&nbsp;' + neote.pkg.name,
    title: "Click to say hello again",
    onclick: function () { neote.toast("Hello again, developer!", "info"); }
  });
});

neote.onDisable(function () {
  // Anything you added in onEnable should be torn down here.
  neote.statusBar.remove("neote-hello");
  neote.log("neote-hello disabled", "warn");
});

// neote-clock — a live clock widget for the status bar.
// Shows how to use setInterval inside a package and tear it down on disable.

neote.onEnable(function () {
  neote.log("neote-clock enabled", "success");

  var ICON = '<i class="fa-regular fa-clock text-neote-violet"></i>&nbsp;';

  function tick() {
    var t = new Date().toLocaleTimeString([], { hour12: false });
    neote.statusBar.update("neote-clock", ICON + t);
  }

  // Seed the widget immediately so it never shows "--:--:--".
  neote.statusBar.add({
    id: "neote-clock",
    position: "right",
    html: ICON + "--:--:--",
    title: "Live clock (updates every second)"
  });

  tick();
  neote._timer = setInterval(tick, 1000);
});

neote.onDisable(function () {
  if (neote._timer) clearInterval(neote._timer);
  neote.statusBar.remove("neote-clock");
  neote.log("neote-clock disabled", "warn");
});

// neote-wordcount — live word/character counts in the status bar.
// Demonstrates editor event subscriptions (onCursor / onChange) and cleanup.

neote.onEnable(function () {
  neote.log("neote-wordcount enabled", "success");

  var ICON = '<i class="fa-solid fa-align-left text-sky-400"></i>&nbsp;';

  function refresh() {
    var text = neote.editor.getValue() || "";
    var words = (text.trim().match(/\S+/g) || []).length;
    var chars = text.length;
    neote.statusBar.update("neote-wordcount", ICON + words + "w / " + chars + "c");
  }

  neote.statusBar.add({
    id: "neote-wordcount",
    position: "right",
    html: ICON + "0w / 0c",
    title: "Words / characters in the active file"
  });

  // Each subscription returns an unsubscribe function — call it on disable.
  neote._cursorSub = neote.editor.onCursor(refresh);
  neote._changeSub = neote.editor.onChange(refresh);
  refresh();
});

neote.onDisable(function () {
  if (neote._cursorSub) neote._cursorSub();
  if (neote._changeSub) neote._changeSub();
  neote.statusBar.remove("neote-wordcount");
  neote.log("neote-wordcount disabled", "warn");
});

// neote-themes — cycle the IDE accent color from the status bar or terminal.
// Demonstrates: clickable widgets, command registration, and DOM attribute theming.

neote.onEnable(function () {
  neote.log("neote-themes enabled", "success");

  var themes = [
    { id: "purple", label: "Purple" },
    { id: "ocean",  label: "Ocean"  },
    { id: "forest", label: "Forest" },
    { id: "sunset", label: "Sunset" },
    { id: "rose",   label: "Rose"   }
  ];
  var idx = 0;

  function apply() {
    var t = themes[idx];
    document.documentElement.setAttribute("data-neote-theme", t.id);
    neote.statusBar.update("neote-themes", '<i class="fa-solid fa-palette text-neote-violet"></i>&nbsp;Theme: ' + t.label);
    neote.log("Theme set to " + t.label, "info");
  }

  neote.statusBar.add({
    id: "neote-themes",
    position: "right",
    html: '<i class="fa-solid fa-palette text-neote-violet"></i>&nbsp;Theme: Purple',
    title: "Click to cycle the IDE accent theme",
    onclick: function () { idx = (idx + 1) % themes.length; apply(); }
  });

  // Expose the same action as a terminal command:  theme.cycle()
  neote.command.register("theme.cycle", function () {
    idx = (idx + 1) % themes.length;
    apply();
    return "Theme: " + themes[idx].label;
  }, "Cycle the IDE accent theme");

  apply();
});

neote.onDisable(function () {
  document.documentElement.removeAttribute("data-neote-theme");
  neote.command.unregister("theme.cycle");
  neote.statusBar.remove("neote-themes");
  neote.log("neote-themes disabled (accent reset to Purple)", "warn");
});

// neote-snippets — type snippet.btn() etc. in the terminal to insert code at the cursor.
// Demonstrates: batch command registration and neote.editor.insert.

neote.onEnable(function () {
  neote.log("neote-snippets enabled", "success");

  var snippets = {
    "snippet.btn":      '$btn("Click me") /id="btn1" /class="primary-btn"',
    "snippet.p":        '$p("Your paragraph text here.")',
    "snippet.hd":       '$hd("Section Title")',
    "snippet.input":    '$input("Placeholder text...") /id="inp1"',
    "snippet.div":      '$div("Container content") /class="box"',
    "snippet.notify":   'notify("Hello from Neote!")',
    "snippet.showcase": 'showcase("Logged value: " + value);'
  };

  neote._names = Object.keys(snippets);

  for (var i = 0; i < neote._names.length; i++) {
    (function (name, text) {
      neote.command.register(name, function () {
        neote.editor.insert(text + "\n");
        return "Inserted: " + name;
      }, "Insert snippet — " + text.slice(0, 24));
    })(neote._names[i], snippets[neote._names[i]]);
  }

  neote.statusBar.add({
    id: "neote-snippets",
    position: "left",
    html: '<i class="fa-solid fa-code text-amber-300"></i>&nbsp;Snippets: ' + neote._names.length,
    title: "Try snippet.btn(), snippet.p(), snippet.hd() ... in the terminal"
  });
});

neote.onDisable(function () {
  for (var i = 0; i < neote._names.length; i++) {
    neote.command.unregister(neote._names[i]);
  }
  neote.statusBar.remove("neote-snippets");
  neote.log("neote-snippets disabled", "warn");
});
